package com.mamtrex.hospital.patient; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*; public interface PatientRepository extends JpaRepository<Patient,UUID>{Optional<Patient> findByMedicalRecordNumber(String mrn); List<Patient> findByFullNameContainingIgnoreCase(String q); /* Branch-scoped workflow reads (docs/plan3.md Task 4): a cross-branch id resolves to empty, indistinguishable from nonexistent. */ Optional<Patient> findByIdAndBranchId(UUID id,UUID branchId); List<Patient> findByBranchId(UUID branchId); List<Patient> findByBranchIdAndFullNameContainingIgnoreCase(UUID branchId,String q); }
